import{_ as h,C as o,o as p,c as w,j as t,a,E as s,a8 as d}from"./chunks/framework.27XeWUA0.js";const r="/schedule-dashboard/thumbs/yt/O_zcc6Xl12g-640.webp",u="/schedule-dashboard/thumbs/yt/O_zcc6Xl12g-1280.webp",n="/schedule-dashboard/thumbs/yt/V8SZ6cJ6q5U-640.webp",m="/schedule-dashboard/thumbs/yt/V8SZ6cJ6q5U-1280.webp",i="/schedule-dashboard/thumbs/yt/qy4ajsBbOKw-640.webp",g="/schedule-dashboard/thumbs/yt/qy4ajsBbOKw-1280.webp",I=JSON.parse('{"title":"AI Digest · Sun 15 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-11-15","routine":"digest"},"relativePath":"digest/2026-11-15.md","filePath":"digest/[date].md"}'),b={name:"digest/2026-11-15.md"},v=r+" 640w, "+u+" 1280w",f=n+" 640w, "+m+" 1280w",y=i+" 640w, "+g+" 1280w",k={id:"ai-digest-·-sun-15-nov-2026",tabindex:"-1"};function _(S,e,q,B,O,z){const l=o("Badge"),c=o("DayFilter");return p(),w("div",null,[t("h1",k,[e[0]||(e[0]=a("AI Digest · Sun 15 Nov 2026 ",-1)),s(l,{type:"tip",text:"3"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-sun-15-nov-2026","aria-label":'Permalink to "AI Digest · Sun 15 Nov 2026 <Badge type="tip" text="3" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 15 Nov 2026 · run date Sun 15 Nov 2026 · 3 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(' 1 new talk: Lauren Tan (SpaceXSI) on how her team ships 11,000 AI-written PRs a month at a 0.5% revert rate (14 Nov, 6:30 PM IST). The "software factory" theme is well covered, but this one is unusually concrete, so not mostly a repeat.')]),t("p",null,[t("strong",null,"Better Stack:"),a(" 2 new videos. The freshest is a hands-on test of Claude Fable 5.2 building a Windows-95-style OS for an ESP32-S3 microcontroller (14 Nov, 8:15 PM IST). There's also a short look at Kiri, a Rust Docker Desktop alternative (14 Nov, 12:15 PM IST). Neither is mostly a repeat.")])],-1)),s(c),e[5]||(e[5]=d('<div class="grid cards2"><article class="it full" id="v-O_zcc6Xl12g" data-title="All Code Is Slop (Except Mine) — Lauren Tan, SpaceXSI" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=O_zcc6Xl12g" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+v+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=O_zcc6Xl12g" target="_blank" rel="noopener">All Code Is Slop (Except Mine) — Lauren Tan, SpaceXSI</a></h3><div class="meta">AI Engineer · Lauren Tan (&quot;poteto&quot;), Grok Bot team at SpaceXSI · uploaded 14 Nov, 6:30 PM IST · 17:32</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — familiar &quot;software factory&quot; theme, but unusually concrete rules (ban useEffect, ban comments, lint over prose) and real numbers.</div><div class="repeat">🔁 Repeat: &#39;software factory&#39; — seen 22 times before. New here: she argues against jumping to a factory first; the payoff comes from deterministic guardrails in the codebase itself.</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 40 times before. New here: concrete use of TLA+ and Lean formal verification plus property-based UI testing (Bombadil) on a shipping desktop app.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 85 times before. New here: hard numbers from one team (11,000 PRs a month, ~0.5% revert rate, 227 contributors).</div><div class="sh">Trust comes from the codebase, not prompts</div><ul><li><strong>3,000 PRs in a month:</strong> She personally shipped about 3,000 pull requests to production last month, and says the engineer&#39;s job now is keeping or raising code quality while massively raising output; it took her 6 months to get there (<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=40s" target="_blank" rel="noopener">0:40</a>–<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=119s" target="_blank" rel="noopener">1:59</a>)</li><li><strong>The inverse trust pyramid:</strong> Spend most effort on deterministic layers first (API design, architecture, lint rules, types, tests), then runtime and formal verification, and only a thin layer of prose (rules, skills, AGENTS.md); every correction to an agent should become a code check, not another rule line (<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=123s" target="_blank" rel="noopener">2:03</a>–<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=211s" target="_blank" rel="noopener">3:31</a>)</li><li><strong>Codebase as a garden:</strong> Review load went from ~3 PRs a day in 2024 to ~300; agents copy whatever pattern they see, so workarounds, deprecated code and anti-patterns spread like weeds unless the codebase is kept pristine (repeat) (<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=211s" target="_blank" rel="noopener">3:31</a>–<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=299s" target="_blank" rel="noopener">4:59</a>)</li></ul><div class="sh">Enforcing architecture with lint rules</div><ul><li><strong>Dune framework:</strong> Dune, their &quot;Next.js for Electron apps&quot;, bans React useEffect in product code (only allowed inside Dune APIs), which removed that whole class of review comments (<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=300s" target="_blank" rel="noopener">5:00</a>–<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=365s" target="_blank" rel="noopener">6:05</a>)</li><li><strong>Context through directories:</strong> Top-level electron-main and electron-renderer folders, with cross-imports blocked by a dependency-graph analyzer and lint rules, stop agents pulling main-thread code into the renderer and causing jank (<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=366s" target="_blank" rel="noopener">6:06</a>–<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=410s" target="_blank" rel="noopener">6:50</a>)</li><li><strong>99% of comments banned:</strong> In Cursor, agents patched an architecture clash with setTimeout / requestAnimationFrame timers and wrote comments justifying it, which hurt performance through GC churn; Grok Bot now bans almost all comments and uses lint errors that tell the agent to fix the root cause (<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=424s" target="_blank" rel="noopener">7:04</a>–<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=580s" target="_blank" rel="noopener">9:40</a>)</li></ul><div class="sh">Verification is where the tokens go</div><ul><li><strong>Runtime verification + feature maps:</strong> Agents run the app themselves via Chrome DevTools Protocol, guided by a &quot;feature map&quot; (a user-facing sitemap of features) and reusable custom CLIs that cut tokens; review now means checking videos, screenshots and diagrams (<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=580s" target="_blank" rel="noopener">9:40</a>–<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=650s" target="_blank" rel="noopener">10:50</a>)</li><li><strong>Formal methods:</strong> TLA+ model-checks flows like cross-device notifications, Lean proves their custom virtualization library has no flicker/jitter, and Bombadil does property-based UI testing; all have already caught real bugs (<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=650s" target="_blank" rel="noopener">10:50</a>–<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=711s" target="_blank" rel="noopener">11:51</a>)</li><li><strong>70% of tokens on verification:</strong> Citing a peer who now spends 70% of daily tokens on verification, she says the same holds for her, and introduces a &quot;state chart&quot; skill in her pstack plugin to visualize state machines for review (<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=713s" target="_blank" rel="noopener">11:53</a>–<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=800s" target="_blank" rel="noopener">13:20</a>)</li></ul><div class="sh">Results</div><ul><li><strong>11,000 PRs, 0.5% reverts:</strong> The team shipped 11,000 PRs last month, cuts a stable release about daily, had 227 contributors in October, and the revert rate held at ~0.5% while startup, typing and chat-switching got faster (<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=812s" target="_blank" rel="noopener">13:32</a>–<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=911s" target="_blank" rel="noopener">15:11</a>)</li><li><strong>Auto-fuzzing releases:</strong> Each new release spins up a Cursor project that fuzzes the whole app like a user, opens fix PRs and auto-merges them; most product code no longer needs deep human review (<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=960s" target="_blank" rel="noopener">16:00</a>–<a href="https://www.youtube.com/watch?v=O_zcc6Xl12g&amp;t=1040s" target="_blank" rel="noopener">17:20</a>)</li></ul></div></article><article class="it full" id="v-V8SZ6cJ6q5U" data-title="Did Fable 5.2 Just Build Windows 95 for a Microcontroller?" data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+f+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U" target="_blank" rel="noopener">Did Fable 5.2 Just Build Windows 95 for a Microcontroller?</a></h3><div class="meta">Better Stack · Andris (Better Stack) · uploaded 14 Nov, 8:15 PM IST · 17:07</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — fun, concrete demo of a frontier model doing real embedded work; skim from <a href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U&amp;t=465s" target="_blank" rel="noopener">7:45</a> if you don&#39;t care about the soldering.</div><div class="repeat">🔁 Repeat: &#39;LLM releases / benchmarks&#39; — seen 47 times before. New here: not a benchmark rundown but a hands-on hardware build testing Claude Fable 5.2 on a real ESP32-S3.</div><div class="sh">Building the hardware</div><ul><li><strong>The challenge:</strong> Anthropic&#39;s demo had Fable 5.2 build a laptop OS with 1,000+ subagents over 8 days; he tried an OS for an ESP32-S3 (2 cores at 240 MHz, 16 MB flash, 8 MB PSRAM, ~300 KB fast RAM) on a single Claude Max subscription (<a href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U&amp;t=123s" target="_blank" rel="noopener">2:03</a>)</li><li><strong>VGA instead of HDMI:</strong> HDMI needs ~250 million bits/s per data line, far beyond the chip&#39;s pins, so he soldered a resistor VGA adapter (440 Ω bright bit + 1 kΩ dim bit per colour = 64 colours); the monitor rejected the standard 25.175 MHz clock until the agent switched to 26.67 MHz (<a href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U&amp;t=123s" target="_blank" rel="noopener">2:03</a>–<a href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U&amp;t=374s" target="_blank" rel="noopener">6:14</a>)</li><li><strong>Input and case:</strong> Neither onboard USB-C port could host a keyboard/mouse, so he added two USB-C breakouts (data + 5 V power), and Opus designed a 3D-printed box (<a href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U&amp;t=374s" target="_blank" rel="noopener">6:14</a>–<a href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U&amp;t=456s" target="_blank" rel="noopener">7:36</a>)</li></ul><div class="sh">How Fable worked</div><ul><li><strong>Own eyes and hands:</strong> With a JetKVM feeding the screen to Chrome and acting as keyboard/mouse, Fable also built a serial channel to dump pixel-perfect PNG screenshots and inject clicks for testing (<a href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U&amp;t=465s" target="_blank" rel="noopener">7:45</a>–<a href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U&amp;t=554s" target="_blank" rel="noopener">9:14</a>)</li><li><strong>Designing around slow memory:</strong> Screen memory sits in PSRAM writable at only 35 MB/s, so the mouse pointer is painted like a hardware sprite (60 FPS, zero memory writes) and &quot;chasing the beam&quot; removed tearing; a full-screen copy dropped from 6.9 ms to 0.55 ms (<a href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U&amp;t=554s" target="_blank" rel="noopener">9:14</a>–<a href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U&amp;t=631s" target="_blank" rel="noopener">10:31</a>)</li></ul><div class="sh">What Bevel OS can do</div><ul><li><strong>Desktop and apps:</strong> Windows-95-style window manager, taskbar, Alt+Tab, widget toolkit, file manager, text editor, Unix-style terminal on a 12 MB flash drive; boots in 0.7 s (target was 3 s) and drags windows at 68 FPS (<a href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U&amp;t=631s" target="_blank" rel="noopener">10:31</a>–<a href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U&amp;t=729s" target="_blank" rel="noopener">12:09</a>)</li><li><strong>Snake, Doom, browser:</strong> Loadable apps include a 4.8 KB Snake and a 348 KB Doom (doomgeneric) at ~32 FPS with dithering, plus a text-only HTTPS browser over Wi-Fi using FrogFind since Google needs JavaScript (<a href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U&amp;t=729s" target="_blank" rel="noopener">12:09</a>–<a href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U&amp;t=883s" target="_blank" rel="noopener">14:43</a>)</li><li><strong>Limits and totals:</strong> Wi-Fi password stored in plain text and crashing apps can reboot the system; one session of just over an hour produced ~11,000 lines of C into a 1.9 MB OS, and the hardest part was his own soldering (<a href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U&amp;t=883s" target="_blank" rel="noopener">14:43</a>–<a href="https://www.youtube.com/watch?v=V8SZ6cJ6q5U&amp;t=983s" target="_blank" rel="noopener">16:23</a>)</li></ul></div></article><article class="it full" id="v-qy4ajsBbOKw" data-title="Docker Desktop Has a New Competitor. It&#39;s Built in Rust" data-channel="Better Stack" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=qy4ajsBbOKw" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+y+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=qy4ajsBbOKw" target="_blank" rel="noopener">Docker Desktop Has a New Competitor. It&#39;s Built in Rust</a></h3><div class="meta">Better Stack · Josh (Better Stack) · uploaded 14 Nov, 12:15 PM IST · 7:13</div><div class="verdict v-skim"><b>Verdict:</b> skim — short tool intro; the local domains and one-click sharing (<a href="https://www.youtube.com/watch?v=qy4ajsBbOKw&amp;t=144s" target="_blank" rel="noopener">2:24</a>) are the interesting part.</div><div class="repeat">🔁 Repeat: &#39;free dev tools&#39; — seen 16 times before. New here: Kiri itself, a Rust Docker-compatible runtime not covered before.</div><div class="sh">What Kiri is</div><ul><li><strong>Claim:</strong> Kiri starts a tiny container in 22 ms, nearly 8× faster than Docker Desktop, with the same Docker commands, Compose files and Dockerfiles (<a href="https://www.youtube.com/watch?v=qy4ajsBbOKw&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=qy4ajsBbOKw&amp;t=30s" target="_blank" rel="noopener">0:30</a>)</li><li><strong>Runs everywhere:</strong> Small custom Linux VM on Mac, WSL2 on Windows, directly on the host on Linux; the daemon uses ~10 MB RAM and the VM shuts down after 60 s idle and boots back in ~0.1 s (<a href="https://www.youtube.com/watch?v=qy4ajsBbOKw&amp;t=30s" target="_blank" rel="noopener">0:30</a>–<a href="https://www.youtube.com/watch?v=qy4ajsBbOKw&amp;t=64s" target="_blank" rel="noopener">1:04</a>)</li><li><strong>Drop-in setup:</strong> Installing creates a &quot;kiri&quot; Docker context, so it can sit beside Docker Desktop and you just switch contexts (<a href="https://www.youtube.com/watch?v=qy4ajsBbOKw&amp;t=72s" target="_blank" rel="noopener">1:12</a>–<a href="https://www.youtube.com/watch?v=qy4ajsBbOKw&amp;t=105s" target="_blank" rel="noopener">1:45</a>)</li></ul><div class="sh">Features beyond speed</div><ul><li><strong>Local domains and sharing:</strong> Containers get local domain names (optional HTTPS on Mac) with no port mapping, and a Share button gives a public link to a locally running app (needs a Kiri cloud account) (<a href="https://www.youtube.com/watch?v=qy4ajsBbOKw&amp;t=144s" target="_blank" rel="noopener">2:24</a>–<a href="https://www.youtube.com/watch?v=qy4ajsBbOKw&amp;t=204s" target="_blank" rel="noopener">3:24</a>)</li><li><strong>Why it&#39;s faster:</strong> Instead of dockerd → containerd → runc → shims, a small daemon talks to an agent in Linux that starts containers with clone3 in their own namespaces; the 10 MB figure is only the daemon, not the VM (<a href="https://www.youtube.com/watch?v=qy4ajsBbOKw&amp;t=204s" target="_blank" rel="noopener">3:24</a>–<a href="https://www.youtube.com/watch?v=qy4ajsBbOKw&amp;t=270s" target="_blank" rel="noopener">4:30</a>)</li><li><strong>Not a clean sweep:</strong> In Kiri&#39;s own tests Colima reads bind mounts faster and OrbStack handles more new HTTP connections/s; it imports Docker Desktop/OrbStack images and offers single-node Kubernetes in ~20 s (<a href="https://www.youtube.com/watch?v=qy4ajsBbOKw&amp;t=270s" target="_blank" rel="noopener">4:30</a>–<a href="https://www.youtube.com/watch?v=qy4ajsBbOKw&amp;t=349s" target="_blank" rel="noopener">5:49</a>)</li></ul><div class="sh">Caveats</div><ul><li><strong>Still beta:</strong> It&#39;s new and in beta; networking, volumes, permissions, builds and Compose edge cases make replacing Docker a big job, so try it but don&#39;t uninstall Docker (<a href="https://www.youtube.com/watch?v=qy4ajsBbOKw&amp;t=349s" target="_blank" rel="noopener">5:49</a>–<a href="https://www.youtube.com/watch?v=qy4ajsBbOKw&amp;t=433s" target="_blank" rel="noopener">7:13</a>)</li></ul></div></article></div>',1))])}const V=h(b,[["render",_]]);export{I as __pageData,V as default};
